import{ar as n,as as a,at as e,au as t}from"./app-CUiZF7NJ.js";const p={};function o(l,s){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="四、运算符" tabindex="-1"><a class="header-anchor" href="#四、运算符"><span>四、运算符</span></a></h1><p><strong>运算符（Operator）</strong> 也叫操作符，是用于对一个或多个操作数（值）进行运算的符号。JavaScript 提供了丰富的运算符，本章将逐一介绍。</p><h2 id="_4-1-算术运算符" tabindex="-1"><a class="header-anchor" href="#_4-1-算术运算符"><span>4.1 算术运算符</span></a></h2><p>算术运算符用于执行基本的数学运算。</p><table><thead><tr><th>运算符</th><th>名称</th><th>示例</th><th>结果</th></tr></thead><tbody><tr><td><code>+</code></td><td>加法</td><td><code>1 + 1</code></td><td><code>2</code></td></tr><tr><td><code>-</code></td><td>减法</td><td><code>10 - 5</code></td><td><code>5</code></td></tr><tr><td><code>*</code></td><td>乘法</td><td><code>2 * 4</code></td><td><code>8</code></td></tr><tr><td><code>/</code></td><td>除法</td><td><code>10 / 5</code></td><td><code>2</code></td></tr><tr><td><code>**</code></td><td>幂运算</td><td><code>2 ** 4</code></td><td><code>16</code></td></tr><tr><td><code>%</code></td><td>模运算（取余）</td><td><code>10 % 3</code></td><td><code>1</code></td></tr></tbody></table><h3 id="_4-1-1-基本运算示例" tabindex="-1"><a class="header-anchor" href="#_4-1-1-基本运算示例"><span>4.1.1 基本运算示例</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>        <span class="token comment">// 2</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">-</span> <span class="token number">5</span><span class="token punctuation">;</span>           <span class="token comment">// 5</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">2</span> <span class="token operator">*</span> <span class="token number">4</span><span class="token punctuation">;</span>            <span class="token comment">// 8</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">/</span> <span class="token number">5</span><span class="token punctuation">;</span>           <span class="token comment">// 2</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">/</span> <span class="token number">3</span><span class="token punctuation">;</span>           <span class="token comment">// 3.3333333333333335</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">/</span> <span class="token number">0</span><span class="token punctuation">;</span>           <span class="token comment">// Infinity（除以0得无穷）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">**</span> <span class="token number">4</span><span class="token punctuation">;</span>          <span class="token comment">// 10000（10的4次方）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">9</span> <span class="token operator">**</span> <span class="token number">0.5</span><span class="token punctuation">;</span>         <span class="token comment">// 3（开平方）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">%</span> <span class="token number">2</span><span class="token punctuation">;</span>           <span class="token comment">// 0（10除以2余0）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">%</span> <span class="token number">3</span><span class="token punctuation">;</span>           <span class="token comment">// 1（10除以3余1）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-1-2-自动类型转换规则" tabindex="-1"><a class="header-anchor" href="#_4-1-2-自动类型转换规则"><span>4.1.2 自动类型转换规则</span></a></h3><p>JavaScript 是<strong>弱类型语言</strong>，进行算术运算时会自动进行类型转换：</p><table><thead><tr><th>运算场景</th><th>转换规则</th><th>示例</th></tr></thead><tbody><tr><td>非字符串的算术运算</td><td>将非数值转换为数值</td><td><code>10 - &#39;5&#39;</code> → <code>10 - 5</code> → <code>5</code></td></tr><tr><td>任意值 + 字符串</td><td>将其他值转换为字符串进行拼接</td><td><code>&#39;1&#39; + 2</code> → <code>&#39;12&#39;</code></td></tr><tr><td>布尔值参与运算</td><td><code>true</code> → <code>1</code>，<code>false</code> → <code>0</code></td><td><code>10 + true</code> → <code>11</code></td></tr><tr><td><code>null</code> 参与运算</td><td><code>null</code> → <code>0</code></td><td><code>5 + null</code> → <code>5</code></td></tr><tr><td><code>undefined</code> 参与运算</td><td><code>undefined</code> → <code>NaN</code></td><td><code>6 - undefined</code> → <code>NaN</code></td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 自动类型转换示例</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">-</span> <span class="token string">&#39;5&#39;</span><span class="token punctuation">;</span>          <span class="token comment">// 5（&#39;5&#39; 转为 5）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">+</span> <span class="token boolean">true</span><span class="token punctuation">;</span>         <span class="token comment">// 11（true 转为 1）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">5</span> <span class="token operator">+</span> <span class="token keyword">null</span><span class="token punctuation">;</span>          <span class="token comment">// 5（null 转为 0）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token number">6</span> <span class="token operator">-</span> <span class="token keyword">undefined</span><span class="token punctuation">;</span>     <span class="token comment">// NaN（undefined 转为 NaN）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 字符串拼接</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token string">&#39;hello&#39;</span> <span class="token operator">+</span> <span class="token string">&#39;world&#39;</span><span class="token punctuation">;</span> <span class="token comment">// &quot;helloworld&quot;</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token string">&#39;1&#39;</span> <span class="token operator">+</span> <span class="token number">2</span><span class="token punctuation">;</span>           <span class="token comment">// &quot;12&quot;（数字转为字符串拼接）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token operator">+</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span>         <span class="token comment">// &quot;true&quot;（布尔值转为字符串）</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>技巧</strong>：利用 <code>值 + &#39;&#39;</code> 可以将任意值<strong>隐式转换</strong>为字符串，与 <code>String(值)</code> 效果相同但写法更简洁。</p></blockquote><h2 id="_4-2-一元正负" tabindex="-1"><a class="header-anchor" href="#_4-2-一元正负"><span>4.2 一元正负（<code>+</code> / <code>-</code>）</span></a></h2><p>一元运算符只需要一个操作数。</p><table><thead><tr><th>运算符</th><th>名称</th><th>作用</th></tr></thead><tbody><tr><td><code>+</code></td><td>正号</td><td>不改变数值的符号</td></tr><tr><td><code>-</code></td><td>负号</td><td>对数值进行符号取反</td></tr></tbody></table><p><strong>核心特点</strong>：对非数值类型使用正负运算时，会先将其转换为数值再运算。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token operator">-</span><span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token operator">-</span>a<span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 10（负负得正）</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> b <span class="token operator">=</span> <span class="token string">&#39;123&#39;</span><span class="token punctuation">;</span></span>
<span class="line">b <span class="token operator">=</span> <span class="token operator">+</span>b<span class="token punctuation">;</span>          <span class="token comment">// 等价于 b = Number(b)</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> b<span class="token punctuation">,</span> b<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// number 123</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> c <span class="token operator">=</span> <span class="token string">&#39;123&#39;</span><span class="token punctuation">;</span></span>
<span class="line">c <span class="token operator">=</span> <span class="token operator">-</span>c<span class="token punctuation">;</span>          <span class="token comment">// 转为数字并取负</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> c<span class="token punctuation">,</span> c<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// number -123</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>技巧</strong>：利用 <code>+值</code> 可以将任意值<strong>隐式转换</strong>为数值，与 <code>Number(值)</code> 效果相同。</p></blockquote><h2 id="_4-3-自增与自减" tabindex="-1"><a class="header-anchor" href="#_4-3-自增与自减"><span>4.3 自增与自减</span></a></h2><h3 id="_4-3-1-自增" tabindex="-1"><a class="header-anchor" href="#_4-3-1-自增"><span>4.3.1 自增（<code>++</code>）</span></a></h3><p>自增运算符使变量<strong>立即增加 1</strong>。</p><table><thead><tr><th>写法</th><th>名称</th><th>返回值</th><th>对变量的影响</th></tr></thead><tbody><tr><td><code>a++</code></td><td>后自增</td><td><strong>自增前的值</strong>（旧值）</td><td>变量 +1</td></tr><tr><td><code>++a</code></td><td>前自增</td><td><strong>自增后的值</strong>（新值）</td><td>变量 +1</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 后自增：先返回旧值，再自增</span></span>
<span class="line"><span class="token keyword">let</span> b <span class="token operator">=</span> a<span class="token operator">++</span><span class="token punctuation">;</span>   <span class="token comment">// b = 10，a = 11</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>b<span class="token punctuation">,</span> a<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 10 11</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 前自增：先自增，再返回新值</span></span>
<span class="line"><span class="token keyword">let</span> c <span class="token operator">=</span> <span class="token operator">++</span>a<span class="token punctuation">;</span>   <span class="token comment">// a 先变为 12，c = 12</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> a<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 12 12</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-2-自减" tabindex="-1"><a class="header-anchor" href="#_4-3-2-自减"><span>4.3.2 自减（<code>--</code>）</span></a></h3><p>自减运算符使变量<strong>立即减少 1</strong>。</p><table><thead><tr><th>写法</th><th>名称</th><th>返回值</th><th>对变量的影响</th></tr></thead><tbody><tr><td><code>a--</code></td><td>后自减</td><td><strong>自减前的值</strong>（旧值）</td><td>变量 -1</td></tr><tr><td><code>--a</code></td><td>前自减</td><td><strong>自减后的值</strong>（新值）</td><td>变量 -1</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token operator">--</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 9</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> b <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> c <span class="token operator">=</span> <span class="token operator">--</span>b<span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>b<span class="token punctuation">,</span> c<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 9 9（前自减：先减1，再返回值）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-3-综合练习" tabindex="-1"><a class="header-anchor" href="#_4-3-3-综合练习"><span>4.3.3 综合练习</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> n <span class="token operator">=</span> <span class="token number">5</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> result <span class="token operator">=</span> n<span class="token operator">++</span> <span class="token operator">+</span> <span class="token operator">++</span>n <span class="token operator">+</span> n<span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>result<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 计算过程：</span></span>
<span class="line"><span class="token comment">// n++ → 返回 5，n 变为 6</span></span>
<span class="line"><span class="token comment">// ++n → n 先变为 7，返回 7</span></span>
<span class="line"><span class="token comment">// n → 此时 n = 7</span></span>
<span class="line"><span class="token comment">// 结果：5 + 7 + 7 = 19</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-4-逻辑运算符" tabindex="-1"><a class="header-anchor" href="#_4-4-逻辑运算符"><span>4.4 逻辑运算符</span></a></h2><p>逻辑运算符用于执行布尔逻辑运算。</p><h3 id="_4-4-1-逻辑非" tabindex="-1"><a class="header-anchor" href="#_4-4-1-逻辑非"><span>4.4.1 逻辑非（<code>!</code>）</span></a></h3><ul><li>对布尔值取反：<code>true</code> → <code>false</code>，<code>false</code> → <code>true</code></li><li>对非布尔值：先转为布尔值，再取反</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token operator">!</span>a<span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// false</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 双重取反 → 转为布尔值</span></span>
<span class="line"><span class="token keyword">let</span> b <span class="token operator">=</span> <span class="token string">&#39;hello&#39;</span><span class="token punctuation">;</span></span>
<span class="line">b <span class="token operator">=</span> <span class="token operator">!</span><span class="token operator">!</span>b<span class="token punctuation">;</span>         <span class="token comment">// 等价于 Boolean(b)</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>b<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>技巧</strong>：利用 <code>!!值</code> 可以将任意值<strong>隐式转换</strong>为布尔值。</p></blockquote><h3 id="_4-4-2-逻辑与" tabindex="-1"><a class="header-anchor" href="#_4-4-2-逻辑与"><span>4.4.2 逻辑与（<code>&amp;&amp;</code>）</span></a></h3><ul><li>两边都为 <code>true</code> 时返回 <code>true</code>，否则返回 <code>false</code></li><li><strong>短路与</strong>：如果第一个值为 <code>false</code>，则<strong>不会</strong>计算第二个值</li></ul><p><strong>返回值规则（针对非布尔值）</strong>：</p><table><thead><tr><th>条件</th><th>返回值</th></tr></thead><tbody><tr><td>第一个值为 <code>false</code>（假值）</td><td>返回第一个值</td></tr><tr><td>第一个值为 <code>true</code>（真值）</td><td>返回第二个值</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 布尔值运算</span></span>
<span class="line"><span class="token keyword">let</span> result <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token operator">&amp;&amp;</span> <span class="token boolean">true</span><span class="token punctuation">;</span>   <span class="token comment">// true</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token operator">&amp;&amp;</span> <span class="token boolean">false</span><span class="token punctuation">;</span>      <span class="token comment">// false</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token boolean">false</span> <span class="token operator">&amp;&amp;</span> <span class="token boolean">true</span><span class="token punctuation">;</span>      <span class="token comment">// false</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token boolean">false</span> <span class="token operator">&amp;&amp;</span> <span class="token boolean">false</span><span class="token punctuation">;</span>     <span class="token comment">// false</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 短路特性</span></span>
<span class="line"><span class="token boolean">true</span> <span class="token operator">&amp;&amp;</span> <span class="token function">alert</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// alert 会执行（第一个为 true）</span></span>
<span class="line"><span class="token boolean">false</span> <span class="token operator">&amp;&amp;</span> <span class="token function">alert</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// alert 不会执行（第一个为 false，短路）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 非布尔值运算（返回原值）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">&amp;&amp;</span> <span class="token number">2</span><span class="token punctuation">;</span>      <span class="token comment">// 2（1 → true，返回第二个值）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">&amp;&amp;</span> <span class="token number">0</span><span class="token punctuation">;</span>      <span class="token comment">// 0（1 → true，返回第二个值 0）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span> <span class="token number">NaN</span><span class="token punctuation">;</span>    <span class="token comment">// 0（0 → false，返回第一个值）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-4-3-逻辑或" tabindex="-1"><a class="header-anchor" href="#_4-4-3-逻辑或"><span>4.4.3 逻辑或（<code>||</code>）</span></a></h3><ul><li>两边有 <code>true</code> 时返回 <code>true</code>，否则返回 <code>false</code></li><li><strong>短路或</strong>：如果第一个值为 <code>true</code>，则<strong>不会</strong>计算第二个值</li></ul><p><strong>返回值规则（针对非布尔值）</strong>：</p><table><thead><tr><th>条件</th><th>返回值</th></tr></thead><tbody><tr><td>第一个值为 <code>true</code>（真值）</td><td>返回第一个值</td></tr><tr><td>第一个值为 <code>false</code>（假值）</td><td>返回第二个值</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 布尔值运算</span></span>
<span class="line"><span class="token keyword">let</span> result <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token operator">||</span> <span class="token boolean">false</span><span class="token punctuation">;</span>   <span class="token comment">// true</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token boolean">false</span> <span class="token operator">||</span> <span class="token boolean">true</span><span class="token punctuation">;</span>       <span class="token comment">// true</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token operator">||</span> <span class="token boolean">true</span><span class="token punctuation">;</span>        <span class="token comment">// true</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token boolean">false</span> <span class="token operator">||</span> <span class="token boolean">false</span><span class="token punctuation">;</span>      <span class="token comment">// false</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 短路特性</span></span>
<span class="line"><span class="token boolean">false</span> <span class="token operator">||</span> <span class="token function">alert</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// alert 会执行（第一个为 false）</span></span>
<span class="line"><span class="token boolean">true</span> <span class="token operator">||</span> <span class="token function">alert</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// alert 不会执行（第一个为 true，短路）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 非布尔值运算（返回原值）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">||</span> <span class="token number">2</span><span class="token punctuation">;</span>            <span class="token comment">// 1（1 → true，返回第一个值）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token string">&quot;hello&quot;</span> <span class="token operator">||</span> <span class="token number">NaN</span><span class="token punctuation">;</span>    <span class="token comment">// &quot;hello&quot;（&quot;hello&quot; → true）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">NaN</span> <span class="token operator">||</span> <span class="token number">1</span><span class="token punctuation">;</span>          <span class="token comment">// 1（NaN → false，返回第二个值）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-4-4-逻辑运算符总结" tabindex="-1"><a class="header-anchor" href="#_4-4-4-逻辑运算符总结"><span>4.4.4 逻辑运算符总结</span></a></h3><table><thead><tr><th>运算符</th><th>名称</th><th>找值逻辑</th><th>返回值类型</th></tr></thead><tbody><tr><td><code>&amp;&amp;</code></td><td>逻辑与</td><td>找 <code>false</code>，找到就返回</td><td>原值</td></tr><tr><td>\`</td><td></td><td>\`</td><td>逻辑或</td></tr><tr><td><code>!</code></td><td>逻辑非</td><td>取反</td><td>布尔值</td></tr></tbody></table><h2 id="_4-5-关系运算符" tabindex="-1"><a class="header-anchor" href="#_4-5-关系运算符"><span>4.5 关系运算符</span></a></h2><p>关系运算符用于比较两个值之间的关系，成立返回 <code>true</code>，不成立返回 <code>false</code>。</p><table><thead><tr><th>运算符</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td><code>&gt;</code></td><td>大于</td><td><code>10 &gt; 5</code> → <code>true</code></td></tr><tr><td><code>&gt;=</code></td><td>大于等于</td><td><code>5 &gt;= 5</code> → <code>true</code></td></tr><tr><td><code>&lt;</code></td><td>小于</td><td><code>5 &lt; 10</code> → <code>true</code></td></tr><tr><td><code>&lt;=</code></td><td>小于等于</td><td><code>10 &lt;= 5</code> → <code>false</code></td></tr></tbody></table><h3 id="_4-5-1-转换规则" tabindex="-1"><a class="header-anchor" href="#_4-5-1-转换规则"><span>4.5.1 转换规则</span></a></h3><table><thead><tr><th>场景</th><th>转换规则</th><th>示例</th></tr></thead><tbody><tr><td>非数值比较</td><td>先转换为数值再比较</td><td><code>&#39;5&#39; &lt; 10</code> → <code>5 &lt; 10</code> → <code>true</code></td></tr><tr><td>两个字符串比较</td><td><strong>不转数值</strong>，逐位比较 Unicode 编码</td><td><code>&#39;ab&#39; &lt; &#39;b&#39;</code> → <code>true</code></td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 数值比较</span></span>
<span class="line"><span class="token keyword">let</span> result <span class="token operator">=</span> <span class="token number">10</span> <span class="token operator">&gt;</span> <span class="token number">5</span><span class="token punctuation">;</span>      <span class="token comment">// true</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">5</span> <span class="token operator">&gt;</span> <span class="token number">5</span><span class="token punctuation">;</span>           <span class="token comment">// false</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">5</span> <span class="token operator">&gt;=</span> <span class="token number">5</span><span class="token punctuation">;</span>          <span class="token comment">// true</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 自动类型转换</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">5</span> <span class="token operator">&lt;</span> <span class="token string">&#39;10&#39;</span><span class="token punctuation">;</span>        <span class="token comment">// true（&#39;10&#39; → 10）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token string">&#39;1&#39;</span> <span class="token operator">&gt;</span> <span class="token boolean">false</span><span class="token punctuation">;</span>     <span class="token comment">// true（false → 0，1 &gt; 0）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token string">&#39;a&#39;</span> <span class="token operator">&lt;</span> <span class="token string">&#39;b&#39;</span><span class="token punctuation">;</span>       <span class="token comment">// true（a 的编码小于 b）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token string">&#39;z&#39;</span> <span class="token operator">&lt;</span> <span class="token string">&#39;f&#39;</span><span class="token punctuation">;</span>       <span class="token comment">// false（z 的编码大于 f）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token string">&#39;abc&#39;</span> <span class="token operator">&lt;</span> <span class="token string">&#39;b&#39;</span><span class="token punctuation">;</span>     <span class="token comment">// true（先比较第一个字符 a &lt; b）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 字符串数字的比较</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token string">&#39;12&#39;</span> <span class="token operator">&lt;</span> <span class="token string">&#39;2&#39;</span><span class="token punctuation">;</span>      <span class="token comment">// true（逐位比较：&#39;1&#39; &lt; &#39;2&#39;）</span></span>
<span class="line"><span class="token comment">// 如果需要按数值比较，请先转换：</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token function">Number</span><span class="token punctuation">(</span><span class="token string">&#39;12&#39;</span><span class="token punctuation">)</span> <span class="token operator">&lt;</span> <span class="token function">Number</span><span class="token punctuation">(</span><span class="token string">&#39;2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>重要</strong>：比较两个<strong>字符串格式的数字</strong>时，一定要先进行类型转换，否则会按字符编码逐位比较。</p></blockquote><h3 id="_4-5-2-区间判断" tabindex="-1"><a class="header-anchor" href="#_4-5-2-区间判断"><span>4.5.2 区间判断</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> num <span class="token operator">=</span> <span class="token number">60</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 错误写法：5 &lt; num &lt; 10 等价于 (5 &lt; num) &lt; 10 → true &lt; 10 → 1 &lt; 10 → true</span></span>
<span class="line"><span class="token comment">// result = 5 &lt; num &lt; 10;  // 永远为 true！</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 正确写法：使用逻辑与</span></span>
<span class="line"><span class="token keyword">let</span> result <span class="token operator">=</span> <span class="token number">5</span> <span class="token operator">&lt;</span> num <span class="token operator">&amp;&amp;</span> num <span class="token operator">&lt;</span> <span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>result<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// false（60 不在 5~10 之间）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-6-相等运算符" tabindex="-1"><a class="header-anchor" href="#_4-6-相等运算符"><span>4.6 相等运算符</span></a></h2><h3 id="_4-6-1-对比表" tabindex="-1"><a class="header-anchor" href="#_4-6-1-对比表"><span>4.6.1 对比表</span></a></h3><table><thead><tr><th>运算符</th><th>名称</th><th>自动类型转换</th><th>说明</th></tr></thead><tbody><tr><td><code>==</code></td><td>相等</td><td>会转换</td><td>比较值是否相等</td></tr><tr><td><code>===</code></td><td>全等</td><td>不转换</td><td>比较值和类型是否都相等（<strong>推荐</strong>）</td></tr><tr><td><code>!=</code></td><td>不等</td><td>会转换</td><td>比较值是否不相等</td></tr><tr><td><code>!==</code></td><td>不全等</td><td>不转换</td><td>比较值和类型是否不全等（<strong>推荐</strong>）</td></tr></tbody></table><h3 id="_4-6-2-特殊规则" tabindex="-1"><a class="header-anchor" href="#_4-6-2-特殊规则"><span>4.6.2 特殊规则</span></a></h3><table><thead><tr><th>比较组合</th><th>结果</th><th>说明</th></tr></thead><tbody><tr><td><code>null == undefined</code></td><td><code>true</code></td><td>特殊规则</td></tr><tr><td><code>null === undefined</code></td><td><code>false</code></td><td>类型不同</td></tr><tr><td><code>NaN == NaN</code></td><td><code>false</code></td><td>NaN 与任何值都不相等</td></tr><tr><td><code>NaN === NaN</code></td><td><code>false</code></td><td>同上</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 相等运算符（==）</span></span>
<span class="line"><span class="token keyword">let</span> result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">==</span> <span class="token number">1</span><span class="token punctuation">;</span>          <span class="token comment">// true</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">==</span> <span class="token number">2</span><span class="token punctuation">;</span>              <span class="token comment">// false</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">==</span> <span class="token string">&#39;1&#39;</span><span class="token punctuation">;</span>            <span class="token comment">// true（&#39;1&#39; → 1）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token operator">==</span> <span class="token string">&#39;1&#39;</span><span class="token punctuation">;</span>         <span class="token comment">// true（true → 1，&#39;1&#39; → 1）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token keyword">null</span> <span class="token operator">==</span> <span class="token keyword">undefined</span><span class="token punctuation">;</span>   <span class="token comment">// true（特殊规则）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">NaN</span> <span class="token operator">==</span> <span class="token number">NaN</span><span class="token punctuation">;</span>          <span class="token comment">// false（NaN 不与任何值相等）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 全等运算符（===）—— 推荐使用</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">===</span> <span class="token string">&#39;1&#39;</span><span class="token punctuation">;</span>           <span class="token comment">// false（类型不同）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token keyword">null</span> <span class="token operator">===</span> <span class="token keyword">undefined</span><span class="token punctuation">;</span>  <span class="token comment">// false（类型不同）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">===</span> <span class="token number">1</span><span class="token punctuation">;</span>             <span class="token comment">// true</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 不等（!=）</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">!=</span> <span class="token number">1</span><span class="token punctuation">;</span>              <span class="token comment">// false</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">!=</span> <span class="token string">&#39;1&#39;</span><span class="token punctuation">;</span>            <span class="token comment">// false（类型转换后相等）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 不全等（!==）—— 推荐使用</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">!==</span> <span class="token number">1</span><span class="token punctuation">;</span>             <span class="token comment">// false</span></span>
<span class="line">result <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">!==</span> <span class="token string">&#39;1&#39;</span><span class="token punctuation">;</span>           <span class="token comment">// true（类型不同）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>最佳实践</strong>：除非有特殊需求，否则<strong>始终使用 <code>===</code> 和 <code>!==</code></strong>，避免因自动类型转换导致的意外结果。</p></blockquote><h2 id="_4-7-条件运算符-三元运算符" tabindex="-1"><a class="header-anchor" href="#_4-7-条件运算符-三元运算符"><span>4.7 条件运算符（三元运算符）</span></a></h2><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">条件表达式 <span class="token operator">?</span> 表达式<span class="token number">1</span> <span class="token operator">:</span> 表达式<span class="token number">2</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li><p>执行流程</p><ol><li>对条件表达式求值</li><li>如果为 <code>true</code> → 执行并返回<strong>表达式1</strong></li><li>如果为 <code>false</code> → 执行并返回<strong>表达式2</strong></li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">,</span> b <span class="token operator">=</span> <span class="token number">20</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用三元运算符取最大值</span></span>
<span class="line"><span class="token keyword">let</span> max <span class="token operator">=</span> a <span class="token operator">&gt;</span> b <span class="token operator">?</span> a <span class="token operator">:</span> b<span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>max<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 20</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 等价于 if-else 写法</span></span>
<span class="line"><span class="token comment">// if (a &gt; b) {</span></span>
<span class="line"><span class="token comment">//     max = a;</span></span>
<span class="line"><span class="token comment">// } else {</span></span>
<span class="line"><span class="token comment">//     max = b;</span></span>
<span class="line"><span class="token comment">// }</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><h2 id="_4-8-运算符优先级" tabindex="-1"><a class="header-anchor" href="#_4-8-运算符优先级"><span>4.8 运算符优先级</span></a></h2><p>JavaScript 中的运算符有明确的优先级，与数学中&quot;先乘除后加减&quot;类似。</p><ul><li><strong>优先级越高</strong>，越先执行</li><li>优先级相同时，一般按<strong>从左到右</strong>的顺序执行</li><li>使用 <code>( )</code> 可以<strong>手动改变优先级</strong>（括号内先执行）</li></ul><ol><li><p>常见优先级（从高到低）</p><table><thead><tr><th>优先级</th><th>运算符</th><th>说明</th></tr></thead><tbody><tr><td>最高</td><td><code>( )</code></td><td>括号</td></tr><tr><td>高</td><td><code>++</code> <code>--</code> <code>!</code> <code>+</code> <code>-</code>（一元）</td><td>自增/自减/非/正负</td></tr><tr><td>中</td><td><code>**</code></td><td>幂运算</td></tr><tr><td>中</td><td><code>*</code> <code>/</code> <code>%</code></td><td>乘/除/取余</td></tr><tr><td>中</td><td><code>+</code> <code>-</code></td><td>加/减</td></tr><tr><td>低</td><td><code>&lt;</code> <code>&gt;</code> <code>&lt;=</code> <code>&gt;=</code></td><td>关系运算符</td></tr><tr><td>低</td><td><code>==</code> <code>===</code> <code>!=</code> <code>!==</code></td><td>相等运算符</td></tr><tr><td>低</td><td><code>&amp;&amp;</code></td><td>逻辑与</td></tr><tr><td>更低</td><td>\`</td><td></td></tr><tr><td>最低</td><td><code>?:</code></td><td>条件运算符</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">+</span> <span class="token number">2</span> <span class="token operator">*</span> <span class="token number">3</span><span class="token punctuation">;</span>      <span class="token comment">// 7（先乘后加）</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token number">1</span> <span class="token operator">+</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token number">3</span><span class="token punctuation">;</span>        <span class="token comment">// 9（括号改变优先级）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 逻辑运算符优先级：&amp;&amp; 高于 ||</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token number">1</span> <span class="token operator">&amp;&amp;</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token operator">||</span> <span class="token number">3</span><span class="token punctuation">;</span>      <span class="token comment">// 2</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>完整优先级参考</p><p>完整的运算符优先级表格请参考 MDN 文档： <a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Operators/Operator_precedence" target="_blank" rel="noopener noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Operators/Operator_precedence</a></p></li></ol><blockquote><p><strong>建议</strong>：遇到不确定优先级的情况，<strong>使用 <code>( )</code> 明确指定执行顺序</strong>，既能保证结果正确，也提高了代码可读性。</p></blockquote><h2 id="_4-9-类型转换-——-显式与隐式" tabindex="-1"><a class="header-anchor" href="#_4-9-类型转换-——-显式与隐式"><span>4.9 类型转换 —— 显式与隐式</span></a></h2><p>类型转换分为<strong>显式转换</strong>（手动调用函数）和<strong>隐式转换</strong>（自动发生）。</p><table><thead><tr><th>目标类型</th><th>显式转换</th><th>隐式转换（技巧）</th><th>说明</th></tr></thead><tbody><tr><td>字符串</td><td><code>String(值)</code></td><td><code>值 + &#39;&#39;</code></td><td>利用字符串拼接</td></tr><tr><td>数值</td><td><code>Number(值)</code></td><td><code>+值</code></td><td>利用一元正号</td></tr><tr><td>布尔值</td><td><code>Boolean(值)</code></td><td><code>!!值</code></td><td>利用双重取反</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// ── 转换为字符串 ──</span></span>
<span class="line"><span class="token keyword">let</span> x <span class="token operator">=</span> <span class="token number">123</span><span class="token punctuation">;</span></span>
<span class="line">x <span class="token operator">=</span> x <span class="token operator">+</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span>              <span class="token comment">// 隐式转换</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> x<span class="token punctuation">,</span> x<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// string &quot;123&quot;</span></span>
<span class="line"></span>
<span class="line">x <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">x <span class="token operator">=</span> x <span class="token operator">+</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> x<span class="token punctuation">,</span> x<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// string &quot;true&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ── 转换为数值 ──</span></span>
<span class="line"><span class="token keyword">let</span> y <span class="token operator">=</span> <span class="token string">&#39;123&#39;</span><span class="token punctuation">;</span></span>
<span class="line">y <span class="token operator">=</span> <span class="token operator">+</span>y<span class="token punctuation">;</span>                  <span class="token comment">// 隐式转换</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> y<span class="token punctuation">,</span> y<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// number 123</span></span>
<span class="line"></span>
<span class="line">y <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">y <span class="token operator">=</span> <span class="token operator">+</span>y<span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> y<span class="token punctuation">,</span> y<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// number 0</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ── 转换为布尔值 ──</span></span>
<span class="line"><span class="token keyword">let</span> z <span class="token operator">=</span> <span class="token string">&#39;123&#39;</span><span class="token punctuation">;</span></span>
<span class="line">z <span class="token operator">=</span> <span class="token operator">!</span><span class="token operator">!</span>z<span class="token punctuation">;</span>                 <span class="token comment">// 隐式转换</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> z<span class="token punctuation">,</span> z<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// boolean true</span></span>
<span class="line"></span>
<span class="line">z <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">z <span class="token operator">=</span> <span class="token operator">!</span><span class="token operator">!</span>z<span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> z<span class="token punctuation">,</span> z<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// boolean false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,74)])])}const r=n(p,[["render",o]]),d=JSON.parse('{"path":"/script/JavaScript/base/04.html","title":"四、运算符","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790564252000,"contributors":[{"name":"zhao-farmer","username":"zhao-farmer","email":"857899180@qq.com","commits":2,"url":"https://github.com/zhao-farmer"}],"changelog":[{"hash":"cfbbc7f726ec8e4db66fff0788f0c77d25bef9b8","time":1790564252000,"email":"857899180@qq.com","author":"zhao-farmer","message":"前端代码记录"},{"hash":"c70b07d347b059fbe78c7770e7fa611a62f92633","time":1744806830000,"email":"857899180@qq.com","author":"zhao-farmer","message":"前端笔记提交"}]},"filePathRelative":"script/JavaScript/base/04.md"}');export{r as comp,d as data};
